import { SaveNotice } from '../components/SaveNotice';
import { PlannedRouteDurations } from '../components/PlannedRouteDurations';
import { useEffect,useRef,useState } from 'react';
import { apiFetch,ApiError,VehicleRecord,SchoolRecord,StudentRecord,StoredRoute,RouteDirection } from '../services/api';
import { LocationPicker,LocationDraft } from '../components/LocationPicker';
import { SourceBadge,TrafficRouteMap } from '../components/TrafficDetails';
import { localPlanningDate, routePoints } from '../services/routePresentation';
import { WorkspaceDialog } from '../components/WorkspaceDialog';
import { durationLabel, vehicleLabel } from '../services/uiFormat';
import { Sunrise, Sunset, Users, MapPin } from 'lucide-react';
type ImportLocation={external_id:string;event_id:string;status:string;supplied_address:string|null;result_source:string;current_location_confirmed:boolean;provider_result:{formatted_address:string;partial_match:boolean;candidate_count?:number}|null;note:string};
type Decision='yes'|'no'|'unknown';type Evidence='boarded'|'no_show'|'unknown';
type Row={student_id:string;external_id:string;am:Decision;pm:Decision;morning_evidence:Evidence;eligible:boolean;exclusion_reason:string|null};
type Recommendation={mode:string;status:string;recommended_departure_seconds:number|null;preferred_feasible:boolean|null;hard_feasible:boolean|null;estimate_timestamp:string;assumptions:string[];matrix_evaluations?:number;matrix_budget?:number};
const dayTime=(seconds:number)=>`${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds%3600/60)).padStart(2,'0')}`;
type Plan={route:(StoredRoute&{departure_recommendation?:Recommendation;warnings?:string[];preferred_buffer_met?:boolean;end_policy?:string})|null;publication:string;publication_blockers:string[];review:Record<string,unknown>;attendance:{rows:Row[];unknown_attendance:string[];unresolved_boarding:string[];unresolved_afternoon_only:string[]}};
interface Day {location_imports?:ImportLocation[];scenario_id:string;name:string;service_date:string;timezone:string;provenance:string;vehicle:VehicleRecord;schools:SchoolRecord[];students:StudentRecord[];counts:Record<RouteDirection,number>;plans:Record<RouteDirection,Plan>;policy:{afternoon_only:'unresolved'|'allow'|'deny';supplied_depot_address:string;supplied_school_addresses:Record<string,string>;supplied_participant_addresses:Record<string,string>}}
const control='max-w-full border border-slate-200 rounded-lg p-2 bg-white text-sm';
const clock=(value:string|null)=>value?new Date(value).toLocaleTimeString('en-GB',{timeZone:'Asia/Colombo'}):'Unknown';
export function DailyPlan({researchTools=false}:{researchTools?:boolean}){
 const [panel,setPanel]=useState<'attendance'|'prepare'|'locations'|'morning'|'afternoon'|null>(null);
 const inFlight=useRef(false);
 const [registrationJson,setRegistrationJson]=useState(''),[registrationResult,setRegistrationResult]=useState('');
 const [date,setDate]=useState(localPlanningDate),[revision,setRevision]=useState(0),[data,setData]=useState<Day|null>(null);
 const [loading,setLoading]=useState(true),[missing,setMissing]=useState(false),[error,setError]=useState(''),[saving,setSaving]=useState(false),[notice,setNotice]=useState('');
 const [attendance,setAttendance]=useState<Row[]>([]),[evidence,setEvidence]=useState<Row[]>([]),[reason,setReason]=useState('Manual landmark field-test review; no card system connected.');
 const [provider,setProvider]=useState('simulation'),[amTime,setAmTime]=useState('06:00'),[pmTime,setPmTime]=useState('13:30'),[review,setReview]=useState(false),[liveBudget,setLiveBudget]=useState(0),[trafficBudget,setTrafficBudget]=useState(0),[fallback,setFallback]=useState('ml'),[forceFailure,setForceFailure]=useState(false),[roadGeometry,setRoadGeometry]=useState(false);
 const [pmTrip,setPmTrip]=useState(''),[pmStudent,setPmStudent]=useState('TEST_05'),[pmEvent,setPmEvent]=useState<string>(()=>crypto.randomUUID()),[pmObserved,setPmObserved]=useState(()=>new Date().toISOString()),[resolveEvent,setResolveEvent]=useState(''),[boardingFeedback,setBoardingFeedback]=useState('');
 const [target,setTarget]=useState(''),[draft,setDraft]=useState<LocationDraft|null>(null),[supplied,setSupplied]=useState('');
 useEffect(()=>{const c=new AbortController();setLoading(true);setData(null);setError('');setMissing(false);setTarget('');setDraft(null);setReview(false);
  apiFetch<Day>(`/daily-plan?service_date=${date}`,c.signal).then(d=>{if(!c.signal.aborted){setData(d);setAttendance(d.plans.morning.attendance.rows);setEvidence(d.plans.morning.attendance.rows);}})
   .catch(e=>{if(!c.signal.aborted){if(e instanceof ApiError&&e.status===404)setMissing(true);else setError(e.message);}}).finally(()=>{if(!c.signal.aborted)setLoading(false);});return()=>c.abort();
 },[date,revision]);
 async function run(action:()=>Promise<unknown>,message:string){if(inFlight.current)return;inFlight.current=true;setSaving(true);setError('');setNotice('');try{const result=await action() as {regenerated?:{status:string}[]};setNotice(result?.regenerated?.some(p=>['routing_failed_inputs_saved','invalid_input','attendance_unresolved','no_solution_found','infeasible'].includes(p.status))?'Input saved; routing is blocked or failed. Review location/attendance and plan errors.':message);setRevision(n=>n+1);return true;}catch(e){setError(e instanceof Error?e.message:'Request failed. No demonstration result substituted.');return false;}finally{inFlight.current=false;setSaving(false);}}
 function send(kind:string,records:unknown[]){return apiFetch('/daily-plan/import',undefined,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({schema_version:'saferide-routing-provisional/v1',event_id:crypto.randomUUID(),occurred_at:new Date().toISOString(),producer:'manual_test',provenance:'landmark_test',kind,reason,records})});}
 async function sendPM(){const result=await apiFetch<{duplicate:boolean;event_id:string;boarding_result?:{status:string;outcome_state:string}}>('/daily-plan/import',undefined,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({schema_version:'saferide-routing-provisional/v1',event_id:pmEvent,occurred_at:pmObserved,producer:'manual_test',provenance:'landmark_test',kind:'boarding',reason,records:[{student_external_id:pmStudent,service_date:date,direction:'afternoon',trip_id:pmTrip,outcome:'boarded',resolves_event_id:resolveEvent||null}]})});setBoardingFeedback(`${result.event_id}: ${result.duplicate?'Duplicate event ? history retained':result.boarding_result?.status??'Recorded'} / ${result.boarding_result?.outcome_state??'Unchanged'}`);return result;}
 function choose(id:string){if(!data)return;setTarget(id);const school=data.schools.find(s=>s.id===id),p=data.students.find(s=>s.id===id);setDraft({address:school?.address??p?.home_address??data.vehicle.start_address,latitude:String(school?.latitude??p?.home_latitude??(id==='depot'?data.vehicle.start_latitude:null)??''),longitude:String(school?.longitude??p?.home_longitude??(id==='depot'?data.vehicle.start_longitude:null)??''),confirmed:school?.location_confirmed??p?.location_confirmed??data.vehicle.start_confirmed,method:school?.location_method??p?.location_method??data.vehicle.start_method});setSupplied(school?data.policy.supplied_school_addresses[id.replace('MALABE_PP1_','')]:p?data.policy.supplied_participant_addresses[id.replace('MALABE_PP1_','')]:data.policy.supplied_depot_address);}
 async function saveLocation(){if(!draft||!data)return;const payload={address:draft.address,latitude:Number(draft.latitude),longitude:Number(draft.longitude),location_confirmed:true,location_method:draft.method};const options={method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)};
  if(target==='depot'){await apiFetch(`/routing/vehicles/${data.vehicle.id}/locations/start`,undefined,options);await apiFetch(`/routing/vehicles/${data.vehicle.id}/locations/end`,undefined,options);}
  else if(data.schools.some(s=>s.id===target))await apiFetch(`/routing/schools/${target}/location`,undefined,options);
  else{const p=data.students.find(s=>s.id===target)!;await apiFetch(`/routing/students/${p.id}`,undefined,{...options,body:JSON.stringify({name:p.name,school_id:p.school_id,vehicle_id:p.vehicle_id,home_address:draft.address,home_latitude:Number(draft.latitude),home_longitude:Number(draft.longitude),location_confirmed:true,location_method:draft.method,input_source:p.input_source})});}
 }
 useEffect(()=>{setNotice('');},[date]);
 const planClock=(value:string|null)=>value?new Date(value).toLocaleTimeString('en-GB',{timeZone:'Asia/Colombo',hour:'2-digit',minute:'2-digit'}):'Unavailable';
 const seconds=(time:string)=>{const [h,m]=time.split(':').map(Number);return h*3600+m*60;};
 if(!researchTools){
  const dirty=!!data&&JSON.stringify(attendance.map(r=>[r.student_id,r.am,r.pm]))!==JSON.stringify(data.plans.morning.attendance.rows.map(r=>[r.student_id,r.am,r.pm]));
  const primary='inline-flex items-center justify-center gap-2 rounded-lg bg-[#176B87] px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-40';
  const secondary='inline-flex items-center justify-center gap-2 rounded-lg border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium text-[#176B87] disabled:opacity-40';
  const generate=(direction:RouteDirection,recommend=false)=>run(()=>apiFetch('/daily-plan/generate',undefined,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_date:date,direction,provider,live_http_budget:trafficBudget,fallback_policy:fallback,include_geometry:provider==='google'&&roadGeometry,departure_mode:recommend?'recommend':direction==='morning'?'override':'fixed',departure_seconds:seconds(direction==='morning'?amTime:pmTime),...(recommend?{recommendation_live_budget:liveBudget}:{} )})}),recommend?'Departure search saved; review the morning plan.':'Saved route generation completed; review the draft.');
  return <section aria-label="Malabe Daily Plan" className="space-y-6 max-w-7xl mx-auto">
   <div className="bg-white border border-slate-200 shadow-sm rounded-xl p-4 flex flex-wrap items-end gap-4">
    <label className="text-sm font-medium text-slate-600 flex-1 min-w-[140px]">Service date<input aria-label="Daily Plan service date" type="date" disabled={saving} required value={date} onChange={e=>{setDate(e.target.value);setPanel(null);}} className={`${control} block mt-1 w-full`}/></label>
    <label className="text-sm font-medium text-slate-600 flex-1 min-w-[140px]">Vehicle<select aria-label="Daily Plan vehicle" disabled={!data||saving} className={`${control} block mt-1 w-full`} value={data?.vehicle.id??''}>{data?<option value={data.vehicle.id}>{vehicleLabel(data.vehicle.id)} / {data.vehicle.capacity} seats</option>:<option value="">Unavailable</option>}</select></label>
    <span className="text-xs text-slate-500 pb-2">Asia/Colombo · Landmark scenario</span>
   </div>
   {loading&&<p role="status" className="text-sm text-slate-500">Loading dated plan…</p>}{saving&&<p role="status" className="text-sm text-[#176B87]">Saving / planning…</p>}{error&&<p role="alert" className="bg-red-50 text-red-800 rounded-lg p-3 text-sm">{error}</p>}{notice&&<SaveNotice message={notice}/>}{missing&&<p role="alert" className="rounded-lg p-3 bg-amber-50 text-amber-900">Scenario unavailable. Ask an administrator to review scenario setup in administrator tools.</p>}
   {data&&<>
    <section aria-label="Daily transport summary" className="bg-white rounded-xl border border-slate-200 shadow-sm p-5">
     <div className="flex flex-wrap items-center justify-between gap-4"><div><h2 className="font-semibold text-slate-900 flex items-center gap-2"><Users size={19} className="text-[#176B87]"/>Attendance review</h2><p className="mt-1 text-xs text-slate-500">Demonstration assignments · {data.schools.map(s=>s.name).join(' / ')}</p></div><button className={secondary} disabled={saving} onClick={()=>setPanel('attendance')}>Edit attendance</button></div>
     <div className="grid grid-cols-3 gap-3 mt-5"><div><p className="text-xs text-slate-500">Morning</p><p className="text-2xl font-bold text-slate-900 mt-1">{data.counts.morning}</p></div><div><p className="text-xs text-slate-500">Afternoon · provisional</p><p className="text-2xl font-bold text-slate-900 mt-1">{data.counts.afternoon}</p></div><div><p className="text-xs text-slate-500">Unresolved attendance</p><p className="text-2xl font-bold text-slate-900 mt-1">{new Set([...data.plans.morning.attendance.unknown_attendance,...data.plans.afternoon.attendance.unknown_attendance]).size}</p></div></div>
    </section>
    <div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-bold text-slate-900">Morning and afternoon plans</h2><p className="text-sm text-slate-500">Prepare, review, then publish each direction.</p></div><div className="flex flex-wrap gap-2"><button className={secondary} onClick={()=>setPanel('locations')}><MapPin size={16}/>Review locations</button><button className={primary} disabled={saving} onClick={()=>setPanel('prepare')}>Prepare routes</button></div></div>
    <div className="grid lg:grid-cols-2 gap-6">{(['morning','afternoon'] as const).map(direction=>{
     const plan=data.plans[direction],r=plan.route,Icon=direction==='morning'?Sunrise:Sunset;
     const schools=r?.stops.filter(s=>s.school_id&&(direction==='morning'?s.action==='delivery':s.action==='pickup'))??[];
     const blocked=plan.publication_blockers;
     return <section key={direction} aria-label={`${direction} Daily Plan`} className="rounded-xl border border-slate-200 bg-white shadow-sm overflow-hidden">
      <div className="flex items-center justify-between gap-3 px-5 py-4 border-b border-slate-100"><h2 className="font-semibold text-slate-900 flex items-center gap-2"><Icon size={21} className="text-[#176B87]"/>{direction==='morning'?'Morning':'Afternoon'}</h2><span className={`text-xs font-medium px-3 py-1 rounded-full ${plan.publication==='published'?'bg-emerald-50 text-emerald-800':'bg-amber-50 text-amber-800'}`}>{r&&!r.is_current?'Stale':plan.publication}</span></div>
      <div className="p-5 space-y-4"><dl className="grid grid-cols-2 gap-4"><div><dt className="text-xs text-slate-500">Departure · planned</dt><dd className="text-xl font-bold text-slate-900 mt-1">{r?planClock(r.departure):'Unavailable'}</dd></div><div><dt className="text-xs text-slate-500">Estimated duration</dt><dd className="text-xl font-bold text-slate-900 mt-1">{durationLabel(r?.total_duration_seconds)}</dd></div></dl>
       {r&&<div className="flex flex-wrap items-center gap-2"><SourceBadge source={r.provider_source?.duration_source}/><span className="text-xs text-slate-500">Version {r.version} · {r.feasibility_status}</span></div>}
       {r?.departure_recommendation&&<p className="text-sm text-[#176B87]">{r.departure_recommendation.recommended_departure_seconds!=null?`Recommended ${dayTime(r.departure_recommendation.recommended_departure_seconds)}`:'Selected override revalidated'} / {r.departure_recommendation.status==='reduced_buffer'?'Reduced buffer: preferred arrival not met':r.departure_recommendation.status.replace(/_/g,' ')}</p>}
       <ul className="space-y-3">{schools.map(s=><li key={s.event_id} className="flex justify-between items-center gap-3 text-sm border-t pt-3"><span className="text-slate-700">{s.name}</span><span className="text-right whitespace-nowrap font-medium text-slate-800">{planClock(s.arrival)}<small className="block text-xs font-normal text-slate-500">leave {planClock(s.departure)}</small></span></li>)}</ul>
       {!r&&<p className="text-sm text-slate-500">No saved plan. Review attendance and prepare this direction.</p>}
       {r&&!r.is_current&&<p role="alert" className="text-sm text-amber-900">This saved plan is stale. Prepare a replacement before publication.</p>}
       {[...(r?.errors??[]),...blocked].map((b,i)=><p key={i} className="bg-amber-50 text-amber-900 rounded-lg px-3 py-2 text-sm">{b}</p>)}
       {direction==='afternoon'&&plan.publication!=='published'&&plan.attendance.unresolved_boarding.length>0&&<label className="flex gap-2 items-start rounded-lg bg-amber-50 p-3 text-sm text-amber-900"><input aria-label="Review unresolved PM evidence" type="checkbox" checked={review} onChange={e=>setReview(e.target.checked)} className="mt-1"/>I reviewed {plan.attendance.unresolved_boarding.length} unknown morning outcomes for provisional PM publication. This does not confirm boarding.</label>}
       {r?.provider_source?.force_live_failure&&<p className="text-xs text-amber-900">Controlled failure test estimate.</p>}
       {r?.provider_source?.fallback_reasons?.length? <p className="text-xs text-amber-900">Fallback: {r.provider_source.fallback_reasons.join('; ')}</p>:null}
       <div className="flex flex-wrap gap-2 pt-2"><button className={secondary} disabled={!r} onClick={()=>setPanel(direction)}>Open {direction==='morning'?'AM':'PM'} route</button><button className={primary} disabled={saving||!r||!r.is_current||blocked.length>0||reason.trim().length<3||plan.publication==='published'||(direction==='afternoon'&&plan.attendance.unresolved_boarding.length>0&&!review)} onClick={()=>void run(()=>apiFetch('/daily-plan/publish',undefined,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_date:date,direction,route_id:r!.route_id,review_unresolved_boarding:direction==='afternoon'&&review,reason})}),'Route published')}>{plan.publication==='published'?'Published':`Publish reviewed ${direction==='morning'?'AM':'PM'} plan`}</button></div>
       {reason.trim().length<3&&<p className="text-xs text-amber-900">Enter a review reason in Prepare routes before publishing.</p>}
      </div>
     </section>;
    })}</div>
    <WorkspaceDialog title="Edit attendance" open={panel==='attendance'} onClose={()=>{if(!saving){setAttendance(data.plans.morning.attendance.rows);setPanel(null);}}}>
     <p className="text-sm text-slate-500">{date} · {vehicleLabel(data.vehicle.id)}. Unknown is not absent. Save explicitly to update pre-trip plans.</p>
     <div className="overflow-x-auto"><table className="w-full text-sm text-left"><thead><tr><th className="py-2">Participant / school</th><th>AM</th><th>PM</th></tr></thead><tbody>{attendance.map((r,i)=><tr key={r.student_id} className="border-t"><td className="py-3">{r.external_id} / {data.students.find(s=>s.id===r.student_id)?.school_id.replace('MALABE_PP1_','')}</td>{(['am','pm'] as const).map(field=><td key={field}><select disabled={saving} aria-label={`${r.external_id} ${field} attendance`} className={control} value={r[field]} onChange={e=>setAttendance(rows=>rows.map((row,j)=>j===i?{...row,[field]:e.target.value as Decision}:row))}>{['yes','no','unknown'].map(v=><option key={v}>{v}</option>)}</select></td>)}</tr>)}</tbody></table></div>
     <label className="block text-sm">Review reason<input aria-label="Daily Plan change reason" className={`${control} w-full mt-1`} value={reason} onChange={e=>setReason(e.target.value)}/></label>{error&&<p role="alert" className="text-red-800">{error}</p>}
     <button disabled={saving||reason.trim().length<3} className={primary} onClick={()=>void run(()=>send('attendance',attendance.map(r=>({student_external_id:r.external_id,service_date:date,am:r.am,pm:r.pm}))),'Dated attendance saved; affected plans refreshed.').then(ok=>{if(ok)setPanel(null);})}>Save dated attendance</button>{dirty&&<p className="text-xs text-amber-900">Unsaved attendance changes</p>}
    </WorkspaceDialog>
    <WorkspaceDialog title="Prepare routes" open={panel==='prepare'} onClose={()=>{if(!saving)setPanel(null);}}>
     <div className="grid sm:grid-cols-2 gap-4"><label className="text-sm">Estimate provider<select aria-label="Daily Plan provider" className={`${control} block w-full mt-1`} value={provider} onChange={e=>setProvider(e.target.value)}><option value="simulation">Simulation</option><option value="ml">Experimental ML · synthetic training</option><option value="google">Google traffic (paid)</option></select></label><label className="text-sm">Review reason<input aria-label="Plan review reason" className={`${control} w-full mt-1`} value={reason} onChange={e=>setReason(e.target.value)}/></label></div>
     {provider==='google'&&<div className="rounded-lg bg-amber-50 p-4 space-y-3 text-sm"><p>Explicit Google approval. No requests occur until you choose an action below.</p><label className="block">HTTP budget per plan (0–8)<input aria-label="Traffic verification HTTP budget" type="number" min={0} max={8} value={trafficBudget} onChange={e=>setTrafficBudget(Number(e.target.value))} className={`${control} ml-2 w-20`}/></label><label className="block">AM recommendation budget (0–4)<input aria-label="Recommendation live budget" type="number" min={0} max={4} value={liveBudget} onChange={e=>setLiveBudget(Number(e.target.value))} className={`${control} ml-2 w-20`}/></label><label className="block">Fallback<select aria-label="Traffic fallback policy" value={fallback} onChange={e=>setFallback(e.target.value)} className={`${control} ml-2`}><option value="none">None — unavailable</option><option value="ml">Loaded ML only</option><option value="ml_then_baseline">ML then synthetic baseline</option></select></label><label className="flex gap-2"><input type="checkbox" aria-label="Request ordered Google road geometry" checked={roadGeometry} onChange={e=>setRoadGeometry(e.target.checked)}/>Include road geometry within this budget</label></div>}
     <div className="grid sm:grid-cols-2 gap-4">{(['morning','afternoon'] as const).map(d=><div key={d} className="rounded-xl border p-4 space-y-3"><h3 className="font-semibold">{d==='morning'?'Morning':'Afternoon'}</h3><label className="block text-sm">Departure<input aria-label={d==='morning'?'AM departure':'PM departure'} type="time" min={d==='morning'?'06:00':'13:30'} value={d==='morning'?amTime:pmTime} onChange={e=>d==='morning'?setAmTime(e.target.value):setPmTime(e.target.value)} className={`${control} block mt-1 w-full`}/></label>{d==='morning'&&<button className={`${secondary} w-full`} disabled={saving||(provider==='google'&&liveBudget===0)} onClick={()=>void generate('morning',true)}>Recommend AM departure</button>}<button className={`${primary} w-full`} disabled={saving||(provider==='google'&&trafficBudget===0)} onClick={()=>void generate(d)}>{d==='morning'?'Validate AM override':'Generate PM plan'}</button></div>)}</div>

     <p className="text-xs text-slate-500">AM: earliest 06:00; preferred school arrival 07:05, hard 07:15. Departure-time matrix approximation. Service and waiting are included.</p>{error&&<p role="alert" className="text-red-800">{error}</p>}{notice&&<SaveNotice message={notice}/>}
    </WorkspaceDialog>
    <WorkspaceDialog title="Review locations" open={panel==='locations'} onClose={()=>{if(!saving)setPanel(null);}}>
     <div className="flex flex-wrap gap-2"><button className={secondary} onClick={()=>choose('depot')}>Depot / {data.vehicle.start_confirmed&&data.vehicle.end_confirmed?'confirmed':'pending'}</button>{data.schools.map(s=><button key={s.id} className={secondary} onClick={()=>choose(s.id)}>{s.name} / {s.location_confirmed?'confirmed':'pending'}</button>)}{data.students.map(p=><button key={p.id} className={secondary} onClick={()=>choose(p.id)}>{vehicleLabel(p.id)} / {p.location_confirmed?'confirmed':'pending'}</button>)}</div>
     {draft&&<><p className="text-sm text-slate-500">Supplied address: {supplied}</p><LocationPicker landmarkTest value={draft} disabled={saving} home={false} source="simulated" onChange={v=>setDraft(old=>v.method==='google'?{...v,address:old?.address??v.address}:v)}/><button disabled={saving||!draft.confirmed} className={primary} onClick={()=>void run(saveLocation,'Confirmed location saved; pre-trip plans refreshed.')}>Save confirmed location</button></>}{error&&<p role="alert" className="text-red-800">{error}</p>}
    </WorkspaceDialog>
    {(['morning','afternoon'] as const).map(d=>{const r=data.plans[d].route;return <WorkspaceDialog key={d} title={`${d==='morning'?'Morning':'Afternoon'} route`} open={panel===d} onClose={()=>setPanel(null)}>{r&&<><p className="text-sm text-slate-500">{date} · {vehicleLabel(data.vehicle.id)} · Version {r.version} · {data.plans[d].publication}</p><TrafficRouteMap landmarkTest route={r} points={routePoints(r)} orderedStops={r.stops.map(s=>({id:s.event_id,order:s.sequence,name:s.name}))} height={280}/><PlannedRouteDurations route={r} context="Saved plan"/><ol className="space-y-3" aria-label={`${d} ordered stops`}>{r.stops.map(s=><li key={s.event_id} className="flex gap-3 items-start border-t pt-3"><span className="rounded-full bg-blue-50 text-[#176B87] w-8 h-8 flex items-center justify-center shrink-0 font-bold text-sm">{s.sequence}</span><div><p className="font-medium text-sm">{s.name}</p><p className="text-xs text-slate-500">{s.action} / arrival {planClock(s.arrival)} / leave {planClock(s.departure)}</p></div></li>)}</ol></>}</WorkspaceDialog>;})}
   </>}
  </section>;
 }
 return <section className="space-y-5 max-w-6xl mx-auto" aria-label="Malabe Daily Plan">
  <div className="flex flex-wrap justify-between gap-3"><div><h1 className="text-2xl font-bold text-[#176B87]">Daily Plan</h1><p>Malabe landmark field test · Asia/Colombo</p></div><label>Service date <input aria-label="Daily Plan service date" type="date" disabled={saving} required value={date} onChange={e=>setDate(e.target.value)} className={control}/></label></div>
  <p className="bg-amber-50 border rounded-xl p-3 text-sm">Demonstration school assignments and test attendance at real-world landmarks. These are not registered student homes, measured student trips or card-verified boarding. Hasara's API is not connected.</p>
  <nav aria-label="Daily Plan stages" className="grid sm:grid-cols-3 gap-2">{[['review-attendance','1. Review attendance'],['prepare-routes','2. Prepare routes'],['review-publish','3. Review and publish']].map(([id,label])=><a key={id} href={`#${id}`} className="rounded-xl border bg-white p-3 text-sm font-semibold text-[#176B87] hover:bg-blue-50">{label}</a>)}</nav>
  <p className="text-sm">School workflow: select date; save dated attendance; confirm stopping locations; recommend AM departure or validate an override / generate PM; review the saved version; publish each direction explicitly. Adult-only journeys use Settings ? Administrator tools ? Adult research.</p>
  {saving&&<p role="status">Saving / planning... Please wait; do not resubmit.</p>}
  {loading&&<p role="status">Loading dated scenario...</p>}{error&&<p role="alert" className="text-red-700">{error}</p>}{notice&&<SaveNotice message={notice} />}
  {missing&&<button disabled={saving} onClick={()=>void run(()=>apiFetch('/daily-plan/setup',undefined,{method:'POST'}),'Scenario initialized; no paid geocoding performed.')} className={control}>Set up isolated Malabe scenario</button>}
  {data&&<>
   <section aria-label="Daily transport summary" className="rounded-xl border border-slate-200 bg-white p-4">
    <dl className="grid gap-4 sm:grid-cols-3"><div><dt className="text-xs text-slate-500">Vehicle</dt><dd className="mt-1 font-semibold text-slate-900">VAN_01 <span className="text-sm font-normal text-slate-500">· {data.vehicle.capacity} seats</span></dd></div><div><dt className="text-xs text-slate-500">Morning passengers</dt><dd className="mt-1 font-semibold text-slate-900">{data.counts.morning}</dd></div><div><dt className="text-xs text-slate-500">Afternoon passengers · provisional</dt><dd className="mt-1 font-semibold text-slate-900">{data.counts.afternoon}</dd></div></dl>
    <p className="mt-4 border-t border-slate-100 pt-3 text-xs text-slate-500">Schools: {data.schools.map(s=>s.name).join(' · ')}</p>
   </section>
   <h2 id="review-attendance" className="text-lg font-bold text-[#176B87]">1. Review attendance</h2>
   <section className="bg-white rounded-xl border p-4 space-y-3"><h2 className="font-bold">{researchTools?'Dated attendance and manual test evidence':'Dated attendance'}</h2><p className="text-sm">Unknown is not absent. Confirmed morning no-show excludes PM; missing morning evidence does not. Changing the date does not copy another day's attendance.</p>
    <label>Recorded reason <input aria-label="Daily Plan change reason" value={reason} onChange={e=>setReason(e.target.value)} maxLength={500} className={`${control} w-full`}/></label>
    <div className="overflow-auto"><table className="w-full text-sm text-left"><thead><tr><th>Participant / school</th><th>AM attendance</th><th>PM attendance</th>{researchTools&&<th>Morning test evidence</th>}<th>PM eligibility</th></tr></thead><tbody>{attendance.map((r,i)=><tr key={r.student_id} className="border-t"><td className="py-2">{r.external_id} / {data.students.find(s=>s.id===r.student_id)?.school_id.replace('MALABE_PP1_','')}</td>{(['am','pm'] as const).map(field=><td key={field}><select aria-label={`${r.external_id} ${field} attendance`} className={control} value={r[field]} onChange={e=>setAttendance(rows=>rows.map((row,j)=>j===i?{...row,[field]:e.target.value as Decision}:row))}>{(['yes','no','unknown'] as const).map(v=><option key={v}>{v}</option>)}</select></td>)}{researchTools&&<td><select aria-label={`${r.external_id} morning evidence`} className={control} value={evidence[i]?.morning_evidence??'unknown'} onChange={e=>setEvidence(rows=>rows.map((row,j)=>j===i?{...row,morning_evidence:e.target.value as Evidence}:row))}>{(['unknown','boarded','no_show'] as const).map(v=><option key={v}>{v}</option>)}</select></td>}<td>{data.plans.afternoon.attendance.rows.find(row=>row.student_id===r.student_id)?.eligible?'Provisional eligible':'Excluded'}<p className="text-xs">{data.plans.afternoon.attendance.rows.find(row=>row.student_id===r.student_id)?.exclusion_reason}</p></td></tr>)}</tbody></table></div>
    <button disabled={saving||reason.trim().length<3} className={control} onClick={()=>void run(()=>send('attendance',attendance.map(r=>({student_external_id:r.external_id,service_date:date,am:r.am,pm:r.pm}))),'Dated attendance saved; affected pre-trip plans refreshed.')}>Save dated attendance</button>
    {researchTools&&<><button disabled={saving||reason.trim().length<3} className={`${control} ml-2`} onClick={()=>void run(()=>send('boarding',evidence.map(r=>({student_external_id:r.external_id,service_date:date,direction:'morning',outcome:r.morning_evidence}))),'Manual test evidence recorded; applicable PM plan refreshed.')}>Record manual morning test evidence</button>
    <label className="block text-sm">Afternoon-only transport policy (provisional test policy) <select aria-label="Afternoon-only test policy" value={data.policy.afternoon_only} disabled={saving||reason.trim().length<3} className={control} onChange={e=>void run(()=>send('policy',[{afternoon_only:e.target.value}]),'Explicit test policy recorded.')}><option value="unresolved">Unresolved</option><option value="allow">Explicitly allow for this test</option><option value="deny">Explicitly deny for this test</option></select></label></>}
   </section>
   {researchTools&&<>
   <section className="bg-white rounded-xl border p-4 space-y-3"><h2 className="font-bold">Manual PM boarding test evidence</h2><p className="text-sm">Hasara card system is not connected. Use only an isolated ACTIVE afternoon test trip, never the completed physical-phone morning trip. Event IDs, event time, receipt time and review history are retained. No GPS arrival is manufactured by this control.</p><label className="block">Isolated PM trip ID <input aria-label="PM boarding test trip ID" value={pmTrip} onChange={e=>setPmTrip(e.target.value)} className={`${control} w-full`}/></label><label>Participant <select aria-label="PM boarding test participant" value={pmStudent} onChange={e=>setPmStudent(e.target.value)} className={control}>{data.students.map(p=><option key={p.id} value={p.id.replace('MALABE_PP1_','')}>{p.id.replace('MALABE_PP1_','')}</option>)}</select></label><label className="block">Unique test event ID <input aria-label="PM boarding test event ID" value={pmEvent} onChange={e=>setPmEvent(e.target.value)} className={`${control} w-full`}/></label><button className={control} onClick={()=>setPmEvent(crypto.randomUUID())}>New test event ID</button><label className="block">Observed event time (ISO timestamp with offset, e.g. +05:30) <input aria-label="PM boarding test event time" value={pmObserved} onChange={e=>setPmObserved(e.target.value)} className={`${control} w-full`}/></label><label className="block">Resolve earlier evidence event ID (optional; explicit Admin review) <input aria-label="PM boarding resolution event ID" value={resolveEvent} onChange={e=>setResolveEvent(e.target.value)} className={`${control} w-full`}/></label><p className="text-xs">Use Recorded reason above. Late receipt preserves MISSED and its alert until explicit review of valid pre-deadline evidence. Evidence at/after deadline is recorded without an on-time confirmation. Review uses a new event ID and current review timestamp.</p><button disabled={saving||!pmTrip||!pmEvent||!pmObserved||reason.trim().length<3} className={control} onClick={()=>void run(sendPM,'Manual PM test evidence processed; inspect status and pickup history.')}>Record manual PM boarding test event</button>{boardingFeedback&&<p role="status" className="text-sm">{boardingFeedback}</p>}</section>
   <details className="bg-white border rounded-xl p-4"><summary className="font-bold cursor-pointer">Provisional registration/address import</summary><p className="text-sm">Hasara is disconnected. Submit the documented provisional assignment, school or vehicle event. Supplied addresses remain in audit history. An explicit geocoding_http_budget (0-3) authorizes bounded provider lookup; zero makes no paid lookup. Reuse the same event ID for retries.</p><label className="block">Provisional registration event JSON<textarea aria-label="Provisional registration event JSON" className="w-full border rounded p-2 font-mono text-xs" rows={8} value={registrationJson} onChange={e=>setRegistrationJson(e.target.value)}/></label><button disabled={saving||!registrationJson.trim()} className={control} onClick={()=>void run(async()=>{const body=JSON.parse(registrationJson);if(!['assignment','school','vehicle'].includes(body.kind))throw new Error('Use an assignment, school or vehicle location event here.');const result=await apiFetch<{duplicate:boolean;geocoding_counts:Record<string,number>}>('/daily-plan/import',undefined,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});setDraft(null);setTarget('');setRegistrationResult(`${result.duplicate?'Duplicate: original results retained; no repeat lookup.':'Event saved.'} Lookup counts: ${JSON.stringify(result.geocoding_counts)}`);return result;},'Registration input saved; inspect lookup status, review the stopping pin and planning status.')}>Import provisional registration/address event</button></details>{registrationResult&&<p role="status" className="text-sm">{registrationResult}</p>}
   </>}
   <h2 id="prepare-routes" className="text-lg font-bold text-[#176B87]">2. Prepare routes</h2>
   <details className="bg-white rounded-xl border p-4"><summary className="font-semibold cursor-pointer">Review stopping locations</summary><section className="space-y-3 mt-3"><h2 className="font-bold">Location review</h2>
    {(data.location_imports??[]).map(item=><div key={item.event_id+item.external_id} className="border rounded p-3 text-sm"><p>{item.external_id}: {item.status} / {item.result_source} / {item.current_location_confirmed?'Current stopping pin manually confirmed':'Vehicle stopping point review required'}</p><p>Imported supplied address: {item.supplied_address??'Pin-only update'}</p>{item.provider_result&&<p>Provider address/building suggestion: {item.provider_result.formatted_address} / candidates {item.provider_result.candidate_count??'Unknown'}; not an automatically accepted stopping point.</p>}<p>{item.note}</p></div>)}<p className="text-sm">School starts 07:30; hard morning arrival 07:15, preferred 07:05; release 13:30. Use the confirmed/pending status shown for each stopping pin below. Ambiguous addresses stay unchanged until you explicitly correct them.</p>
    <div className="flex flex-wrap gap-2"><button className={control} onClick={()=>choose('depot')}>Depot — {data.vehicle.start_confirmed&&data.vehicle.end_confirmed?'confirmed':'pending'}</button>{data.schools.map(s=><button key={s.id} className={control} onClick={()=>choose(s.id)}>{s.name} — {s.location_confirmed?'confirmed':'pending'}</button>)}{data.students.map(p=><button key={p.id} className={control} onClick={()=>choose(p.id)}>{p.id.replace('MALABE_PP1_','')} — {p.location_confirmed?'confirmed':'pending'}</button>)}</div>
    {draft&&<div className="border-t pt-3"><p className="text-sm">Original supplied address: {supplied}</p><LocationPicker landmarkTest value={draft} disabled={saving} home={false} source="simulated" onChange={v=>setDraft(old=>v.method==='google'?{...v,address:old?.address??v.address}:v)}/><button disabled={saving||!draft.confirmed} className={control} onClick={()=>void run(saveLocation,'Confirmed landmark location saved; dated pre-trip plans refreshed.')}>Save confirmed location</button></div>}
   </section></details>
   {JSON.stringify(attendance.map(r=>[r.student_id,r.am,r.pm]))!==JSON.stringify(data.plans.morning.attendance.rows.map(r=>[r.student_id,r.am,r.pm]))&&<p role="status" className="bg-amber-50 border rounded p-3 text-sm">Unsaved attendance edits: use Save dated attendance first. Recommendations and generated plans use saved server attendance, not these unsaved selections.</p>}
   {reason.trim().length<3&&<p className="text-sm">Save / publication prerequisite: enter a recorded reason of at least 3 characters.</p>}
   <div className="flex flex-wrap gap-3 items-center"><label className="min-w-0 max-w-full">Estimate provider <select aria-label="Daily Plan provider" value={provider} onChange={e=>setProvider(e.target.value)} className={control}><option value="simulation">Deterministic simulation</option><option value="ml">ML prediction — synthetic training</option><option value="google">Google traffic estimate (may incur charges)</option><option value="baseline">Synthetic historical baseline</option><option value="unavailable">Unavailable</option></select></label><label>AM departure <input aria-label="AM departure" type="time" min="06:00" value={amTime} onChange={e=>setAmTime(e.target.value)} className={control}/></label><label>PM departure <input aria-label="PM departure" type="time" min="13:30" value={pmTime} onChange={e=>setPmTime(e.target.value)} className={control}/></label></div>
   <div className="bg-white border rounded-xl p-4 space-y-2"><h2 className="font-bold">Morning departure recommendation</h2><p className="text-sm">Latest feasible minute found from 06:00. Both schools target 07:05; hard latest 07:15. Departure-time matrix approximation, not a fully time-dependent solver. Reduced-buffer results are labelled explicitly.</p><details><summary className="cursor-pointer text-sm">Recommendation request budget</summary><label>Google HTTP request budget (explicit opt-in, maximum 4) <input aria-label="Recommendation live budget" type="number" min="0" max="4" value={liveBudget} onChange={e=>setLiveBudget(Number(e.target.value))} className={control}/></label></details><button disabled={saving||forceFailure||(provider==='google'&&liveBudget===0)} className={control} onClick={()=>void run(()=>apiFetch('/daily-plan/generate',undefined,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_date:date,direction:'morning',provider,departure_mode:'recommend',recommendation_live_budget:liveBudget,fallback_policy:fallback})}),'Departure search saved; inspect recommendation status and current version.')}>Recommend AM departure</button>{(forceFailure||(provider==='google'&&liveBudget===0))&&<p className="text-xs">Recommendation unavailable: {forceFailure?'turn off Controlled adapter failure TEST to search departure times.':'Google recommendation requires an explicit positive HTTP budget.'}</p>}<p className="text-xs">Google search can incur charges and can exhaust its budget without a recommendation. Attendance-driven automatic recomputation never issues Google recommendation requests.</p></div>
   {(provider==='google'||researchTools)&&<details className="bg-white border rounded-xl p-4 space-y-2"><summary className="font-semibold cursor-pointer">Google request approval and limits</summary><h2 className="font-bold">Administrator live traffic verification</h2><p className="text-sm">Select Google above, set a small budget, then generate AM and PM separately for the selected date and departure. Each button saves a new draft version. No automatic fleet calls; estimates are not measured training labels.</p><label>HTTP budget per selected plan (0-8) <input aria-label="Traffic verification HTTP budget" type="number" min="0" max="8" value={trafficBudget} onChange={e=>setTrafficBudget(Number(e.target.value))} className={control}/></label><label>Declared fallback <select aria-label="Traffic fallback policy" value={fallback} onChange={e=>setFallback(e.target.value)} className={control}><option value="none">None ? unavailable if Google fails</option><option value="ml">Loaded ML only</option><option value="ml_then_baseline">ML then synthetic historical baseline</option></select></label>{researchTools&&<><label className="block"><input aria-label="Controlled traffic adapter failure" type="checkbox" checked={forceFailure} onChange={e=>setForceFailure(e.target.checked)}/> Controlled adapter failure TEST ? no external matrix request</label>{forceFailure&&<p className="text-amber-800">TEST injection enabled. Saved results will be marked; turn this off to restore normal provider operation.</p>}</>}<label className="block"><input aria-label="Request ordered Google road geometry" type="checkbox" checked={roadGeometry} onChange={e=>setRoadGeometry(e.target.checked)}/> Request ordered Google road geometry within the selected plan budget</label><p className="text-xs">Geometry may consume one additional request after the matrix. For an 11-location matrix, allow 5 total requests if geometry is wanted. Loading its Google map image is a separate explicit request. No embedded turn-by-turn navigation is implemented.</p><p className="text-xs">For 11 distinct locations a full matrix may need four HTTP chunks. A partial matrix uses the declared per-leg fallback or becomes unavailable. Unsupported dates are never silently shifted.</p></details>}
   <label className="block text-sm"><input type="checkbox" checked={review} onChange={e=>setReview(e.target.checked)}/> I explicitly reviewed unresolved morning evidence for provisional PM operation. This does not manufacture boarding events.</label>
   <div className="grid sm:grid-cols-2 gap-3">{(['morning','afternoon'] as const).map(direction=><div key={direction} className="bg-white border rounded-xl p-4 space-y-2"><h3 className="font-semibold">{direction==='morning'?'Morning / AM':'Afternoon / PM'}</h3><button disabled={saving||(provider==='google'&&!forceFailure&&trafficBudget===0)} className={control} onClick={()=>void run(()=>apiFetch('/daily-plan/generate',undefined,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_date:date,direction,provider,live_http_budget:trafficBudget,fallback_policy:fallback,force_live_failure:provider==='google'&&forceFailure,include_geometry:provider==='google'&&roadGeometry,departure_mode:direction==='morning'?'override':'fixed',departure_seconds:seconds(direction==='morning'?amTime:pmTime)})}),'Saved route generation completed; inspect actual status below.')}>{direction==='morning'?'Validate AM override':'Generate PM plan'}</button>{provider==='google'&&!forceFailure&&trafficBudget===0&&<p className="text-sm text-amber-800">Open Google request approval and limits; authorize a positive budget before generating a live estimate.</p>}</div>)}</div>
   <h2 id="review-publish" className="text-lg font-bold text-[#176B87]">3. Review and publish</h2>
   <div className="grid lg:grid-cols-2 gap-4">{(['morning','afternoon'] as const).map(direction=>{const plan=data.plans[direction],r=plan.route;return <section key={direction} className="bg-white border rounded-xl p-4 space-y-3" aria-label={`${direction} Daily Plan`}><h2 className="font-bold text-lg">{direction==='morning'?'Morning':'Afternoon'} · {plan.publication}</h2>
    {!r&&<p>No saved dated route. No itinerary or duration is fabricated.</p>}{r&&<><p className="font-semibold">Version {r.version} · {r.feasibility_status} · {r.planning_status}</p><p className="text-sm">{plan.publication==='published'?'Published after explicit administrator review.':'Replacement plans are drafts requiring explicit administrator review and publication.'}</p>{!r.is_current&&<p role="alert" className="text-amber-800 text-sm">This saved plan is not current. Do not use its itinerary or departure recommendation as the current pre-trip plan; review the status and regenerate when permitted. Active trip manifests remain fixed.</p>}<SourceBadge source={r.provider_source?.duration_source}/><p className="text-sm">Departure {clock(r.departure)} / estimate {r.provider_source?.snapshot_generated_at?clock(r.provider_source.snapshot_generated_at):'Unknown'}</p>{r.provider_source?.fallback_reasons?.map(reason=><p key={reason} className="text-sm text-amber-800">Fallback: {reason}</p>)}<details><summary className="cursor-pointer text-sm">Provider details and request usage</summary><div className="text-sm bg-slate-50 rounded p-3"><p>Requested: {r.provider_source?.requested_provider??r.request_settings.provider} ? Actual route source: {r.feasibility_status==='feasible'?(r.provider_source?.duration_source??'Unavailable'):'Unavailable (no feasible plan)'}</p><p>Planned departure: {new Date(r.departure).toLocaleString('en-GB',{timeZone:'Asia/Colombo'})} ? Estimate timestamp: {r.provider_source?.snapshot_generated_at?new Date(r.provider_source.snapshot_generated_at).toLocaleString('en-GB',{timeZone:'Asia/Colombo'}):'Unavailable'}</p><p>Mixed matrix sources: {r.provider_source?.matrix_contains_mixed_sources==null?'Unavailable':r.provider_source.matrix_contains_mixed_sources?'Yes':'No'} ? Model: {r.provider_source?.model_version??'Not used'}</p><p className="text-xs">HTTP requests: {r.provider_source?.live_http_requests??'Unavailable'} / budget {r.provider_source?.live_http_budget??'Existing provider limit'}</p>{r.provider_source?.force_live_failure&&<p className="text-amber-800 font-bold">CONTROLLED ADAPTER FAILURE TEST</p>}{r.provider_source?.fallback_reasons?.map(f=><p key={f} className="text-amber-800">Fallback/unavailable reason: {f}</p>)}<p className="text-xs">{r.provider_source?.time_assumption} Estimates are not measured observations.</p></div></details>{r.departure_recommendation&&<div className="bg-slate-50 border rounded-lg p-3 text-sm"><p className="font-bold">{r.is_current?'':'STALE ? '}{r.departure_recommendation.mode==='override'?'Administrator override':'Recommendation'}: {r.departure_recommendation.status==='reduced_buffer'?'Reduced buffer ? preferred 07:05 not met at both schools':r.departure_recommendation.status}</p><p>Recommended departure: {r.departure_recommendation.recommended_departure_seconds!=null?`${dayTime(r.departure_recommendation.recommended_departure_seconds)} Asia/Colombo`:r.departure_recommendation.mode==='override'?'Not calculated for an administrator override':'Unavailable'}</p><p>Selected saved departure: {r.feasibility_status==='feasible'?`${clock(r.departure)} Asia/Colombo`:'No feasible departure selected'}</p><p>Preferred feasibility: {String(r.departure_recommendation.preferred_feasible??'Unknown')} / Hard feasibility: {String(r.departure_recommendation.hard_feasible??'Unknown')}</p><p>Estimated at: {new Date(r.departure_recommendation.estimate_timestamp).toLocaleString('en-GB',{timeZone:'Asia/Colombo'})}</p><p>{r.departure_recommendation.mode==='override'?'Selected time revalidated against both schools; this is not a latest-departure search.':r.departure_recommendation.recommended_departure_seconds!=null?'Latest feasible minute found by bounded heuristic search; no proof of the latest feasible second.':'No recommendation established; an incomplete search is not proof of infeasibility.'} Every school's service arrival/departure is listed below. Total includes final school service, with no morning depot return.</p><section aria-label="Recommendation assumptions" className="mt-2 space-y-1 border-t pt-2"><p className="font-medium">Search limits</p>{r.departure_recommendation.assumptions.map(a=><p key={a}>{a}</p>)}<p>Matrices: {r.departure_recommendation.matrix_evaluations??'Override single matrix'} / budget {r.departure_recommendation.matrix_budget??'1'}</p></section></div>}<PlannedRouteDurations route={r} context="Administrator saved plan" />{r.errors.map(e=><p key={e} className="text-red-700">{e}</p>)}{r.warnings?.map(w=><p key={w} className="text-amber-800">{w}</p>)}
     {r.feasibility_status==='feasible'&&<><ol className="text-sm space-y-2">{r.stops.map(s=><li key={s.event_id} className="border-t pt-2">{s.sequence}. {s.action}: {s.name}<br/>Arrival {clock(s.arrival)} · service {clock(s.eta)}–{clock(s.departure)} · onboard {s.load_before}→{s.load_after}</li>)}</ol><TrafficRouteMap landmarkTest route={r} points={routePoints(r)} orderedStops={r.stops.map(s=>({id:s.event_id,order:s.sequence,name:s.name}))} height={280}/></>}
     <button className={control} disabled={saving||plan.publication_blockers.length>0||reason.trim().length<3} onClick={()=>void run(()=>apiFetch('/daily-plan/publish',undefined,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_date:date,direction,route_id:r.route_id,review_unresolved_boarding:direction==='afternoon'&&review,reason})}),'Route published')}>Publish reviewed {direction==='morning'?'AM':'PM'} plan</button>
    </>}{plan.publication_blockers.map(b=><p key={b} className="text-amber-800 text-sm">Publication blocked: {b}</p>)}{direction==='afternoon'&&plan.attendance.unresolved_boarding.length>0&&<p className="text-amber-800 text-sm">Unknown morning outcomes: {plan.attendance.unresolved_boarding.length}. Explicit review is required; unknown is not no-show.</p>}
   </section>;})}</div>
  </>}
 </section>;
}
